local STRING_DESCRIPTION_BOUGHT = {
    SUCCESS = "购买成功",
    FAILURE = "购买失败",
}


---@type ECSComponent
local ECSComponent = import("Frame.ECS.ECSComponent")
---@class SeasonPassComponent
local SeasonPassComponent = Class("SeasonPassComponent", ECSComponent)

function SeasonPassComponent:__init()
    ECSComponent.__init(self)
    self.scheduleId = nil -- 排期ID
    self.leftSeconds = nil -- 当前排期剩余秒数
    self.exp = nil -- 当前总经验
    self.bought = nil -- 是否买了Pass卡 0:没买 1:买了
    self.drawnLevelRewards = nil -- 已经领取的等级奖励ID列表
    self.drawnCircleRewardsTimes = nil -- 已领取的巅峰奖励次数
    self.products = nil
end

function SeasonPassComponent:__delete()
    self.scheduleId = nil
    self.leftSeconds = nil
    self.exp = nil
    self.bought = nil
    self.drawnLevelRewards = nil
    self.drawnCircleRewardsTimes = nil
    self.products = nil
end

------------ Property ------------

function SeasonPassComponent:AddTimeDrawnCircleRewards(time)
    self.drawnCircleRewardsTimes = self.drawnCircleRewardsTimes + time
end

---SetTotalExp
---@param vExp integer @ 经验值
function SeasonPassComponent:SetTotalExp(vExp)
    self.exp = checkNumber(vExp)
end

---SetBattlePassBought
---@param vState integer @ 0:没买 1:买普通 2:买进阶
function SeasonPassComponent:SetBattlePassBought(vState)
    self.bought = checkNumber(vState)
end

---GetSeasonLeftTime
---获取活动剩余时间
function SeasonPassComponent:GetSeasonLeftTime()
    return self.leftSeconds
end

---InitDrawnLevelRewards
---初始化奖励领取列表
---@param listDrawReward table 奖励已领取列表
function SeasonPassComponent:InitDrawnLevelRewards(listDrawReward)
    self.drawnLevelRewards = listDrawReward or {}
end

---UpdateDrawnLevelRewards
---更新已领取奖励列表
---@param pRewardId integer @ 奖励 Id
function SeasonPassComponent:UpdateDrawnLevelRewards(pRewardId)
    for i, rewardId in ipairs(self.drawnLevelRewards) do
        if rewardId == pRewardId  then return end
    end
    table.insert(self.drawnLevelRewards, pRewardId)
end

---GetRewardDrawnState
---获取奖励的领取状态
---@param pRewardId integer @ 奖励 Id
function SeasonPassComponent:GetRewardDrawnState(pRewardId)
    for i, rewardId in ipairs(self.drawnLevelRewards) do
        if checkNumber(pRewardId) == checkNumber(rewardId) then
            return true
        end
    end
    return false
end

