---SeasonPassHomeReq
---Pass卡入口
---@param cb fun():void @ 回调函数
function SeasonPassComponent:SeasonPassHomeReq(cb)
    GameUtils.Request(Interfaces.PassCardHome, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local jsonData = response.data
        self.scheduleId = checkNumber(jsonData.scheduleId) -- 排期 Id
        self.leftSeconds = checkNumber(jsonData.leftSeconds)
        self.exp = checkNumber(jsonData.exp)
        self.bought = checkNumber(jsonData.bought)  -- 是否购买 BattlePass Plus
        self.drawnLevelRewards = checkTable(jsonData.drawnLevelRewards) -- 已领取的奖励列表
        self.drawnCircleRewardsTimes = checkNumber(jsonData.drawnCircleRewardsTimes) -- 已领取的巅峰奖励次数
        self.products = checkTable(jsonData.products)
        
        --TODO Temp
        --self.scheduleId = 1
        --self.exp = 0
        --self.bought = 0
        --self.drawnLevelRewards = {}
        --self.drawnCircleRewardsTimes = 0
        if cb then
            cb()
