    end)
end

function SeasonPassComponent:SetStatus(isClose)
    self._isClose = (isClose)
end

function SeasonPassComponent:GetStatus()
    return self._isClose
end

---SeasonPassLevelRewards
---Pass卡领取等级奖励
---@param pRewardId integer @ 奖励ID，传0表示一键领取全部
---@param cb fun(rewardData:table):void @ 回调函数
function SeasonPassComponent:SeasonPassLevelRewardsReq(pRewardId, cb)
    GameUtils.Request(Interfaces.PassCardDrawLevelRewards, { rewardId = pRewardId }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local jsonData = response.data
        local rewardData = jsonData.rewards
        GoodsUtils.DrawRewards(rewardData)
        if cb then
            cb(clone(rewardData))
        end
    end)
end

---PassCardBuyReq
---Pass卡购买
---@param pType integer @ pass卡类型 1:基础 2:进阶
---@param cb fun(rewardData:table):void @ 回调函数
function SeasonPassComponent:PassCardBuyReq(pType, cb)
    GameUtils.Request(Interfaces.PassCardBuy, { type = pType }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        GameUtils.Toast(STRING_DESCRIPTION_BOUGHT.SUCCESS)
        self.bought = pType
        local jsonData = response.data
        local rewardData = jsonData.rewards
        local newExp = jsonData.newExp
        if not IsNull(newExp) then
            self.exp = newExp
            BattlePassMgr:RefreshBattlePassLevel(self.exp)
        end
        GoodsUtils.DrawRewards(rewardData)
        if cb then
            cb(clone(rewardData))
        end
    end)
end

---PassCardDrawCircleRewards
---Pass卡领取巅峰奖励
---@param cb fun(rewardData:table):void @ 回调函数
function SeasonPassComponent:PassCardDrawCircleRewardsReq(cb)
    GameUtils.Request(Interfaces.PassCardDrawCircleRewards, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        local jsonData = response.data
        local rewardData = jsonData.rewards
        GoodsUtils.DrawRewards(rewardData)
        self:AddTimeDrawnCircleRewards(BattlePassMgr:GetCircleRewardsTime() or 0)
        if cb then
            cb(clone(rewardData))
        end
    end)
end

---PassCardBuyLevelReq
---Pass卡购买等级
---@param cb fun():void @ 回调函数
function SeasonPassComponent:PassCardBuyLevelReq(addLevel, cb)
    GameUtils.Request(Interfaces.PassCardBuyLevel, { num = addLevel }, function(request, response)
        if checkNumber(response.errCode) ~= 0 then return end
        GameUtils.Toast(STRING_DESCRIPTION_BOUGHT.SUCCESS)
        self.exp = self.exp + SeasonPassConfMgr:GetExpTotalInLevelZone(BattlePassMgr.curUnlockLv, BattlePassMgr.curUnlockLv + addLevel)
        BattlePassMgr.curUnlockLv = BattlePassMgr.curUnlockLv + addLevel
        if cb then
            cb()
        end
    end)
end

------------ Req ------------

return SeasonPassComponent


